CREATE DATABASE IF NOT EXISTS unifecaf_flix CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE unifecaf_flix;

DROP TABLE IF EXISTS filme;
CREATE TABLE filme (
  id INT AUTO_INCREMENT PRIMARY KEY,
  nome VARCHAR(255) NOT NULL,
  sinopse TEXT,
  ano INT,
  duracao VARCHAR(20),
  diretor VARCHAR(255),
  genero VARCHAR(255),
  elenco VARCHAR(500),
  nota_imdb DECIMAL(3,1)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

